CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('ADMIN','TEACHER','STUDENT')),department TEXT,student_code TEXT,active BOOLEAN DEFAULT true,email_verified BOOLEAN DEFAULT false,verify_token TEXT,reset_token TEXT,reset_expires TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id SERIAL PRIMARY KEY,title TEXT NOT NULL,description TEXT,category_id INT REFERENCES categories(id),level TEXT,prerequisites TEXT,thumbnail_key TEXT,teacher_id INT NOT NULL REFERENCES users(id),status TEXT DEFAULT 'pending' CHECK(status IN('pending','published','rejected')),published BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS modules(id SERIAL PRIMARY KEY,course_id INT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,title TEXT NOT NULL,position INT NOT NULL);
CREATE TABLE IF NOT EXISTS lessons(id SERIAL PRIMARY KEY,module_id INT NOT NULL REFERENCES modules(id) ON DELETE CASCADE,title TEXT NOT NULL,type TEXT NOT NULL,file_key TEXT,url TEXT,content TEXT,duration_sec INT DEFAULT 0,position INT NOT NULL);
CREATE TABLE IF NOT EXISTS enrollments(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,course_id INT REFERENCES courses(id) ON DELETE CASCADE,enrolled_at TIMESTAMPTZ DEFAULT now(),UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS progress(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,lesson_id INT REFERENCES lessons(id) ON DELETE CASCADE,position_sec REAL DEFAULT 0,completed BOOLEAN DEFAULT false,completed_at TIMESTAMPTZ,UNIQUE(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS assignments(id SERIAL PRIMARY KEY,course_id INT REFERENCES courses(id) ON DELETE CASCADE,title TEXT NOT NULL,instructions TEXT,due_at TIMESTAMPTZ NOT NULL,max_points INT DEFAULT 100);
CREATE TABLE IF NOT EXISTS submissions(id SERIAL PRIMARY KEY,assignment_id INT REFERENCES assignments(id) ON DELETE CASCADE,user_id INT REFERENCES users(id) ON DELETE CASCADE,text TEXT,file_key TEXT,late BOOLEAN DEFAULT false,grade REAL,feedback TEXT,submitted_at TIMESTAMPTZ DEFAULT now(),graded_at TIMESTAMPTZ,UNIQUE(assignment_id,user_id));
CREATE TABLE IF NOT EXISTS quizzes(id SERIAL PRIMARY KEY,course_id INT REFERENCES courses(id) ON DELETE CASCADE,title TEXT NOT NULL,time_limit_min INT DEFAULT 10,max_attempts INT DEFAULT 2,pass_pct REAL DEFAULT 60,randomize BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS questions(id SERIAL PRIMARY KEY,quiz_id INT REFERENCES quizzes(id) ON DELETE CASCADE,type TEXT NOT NULL,prompt TEXT NOT NULL,options JSONB DEFAULT '[]',answer TEXT NOT NULL,topic TEXT DEFAULT 'General');
CREATE TABLE IF NOT EXISTS quiz_attempts(id SERIAL PRIMARY KEY,quiz_id INT REFERENCES quizzes(id) ON DELETE CASCADE,user_id INT REFERENCES users(id) ON DELETE CASCADE,score INT,total INT,percentage REAL,passed BOOLEAN,topics JSONB,taken_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance(id SERIAL PRIMARY KEY,course_id INT REFERENCES courses(id) ON DELETE CASCADE,class_date DATE NOT NULL,user_id INT REFERENCES users(id) ON DELETE CASCADE,status CHAR(1) CHECK(status IN('P','A','L')),UNIQUE(course_id,class_date,user_id));
CREATE TABLE IF NOT EXISTS certificates(id SERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,user_id INT REFERENCES users(id),course_id INT REFERENCES courses(id),issued_at TIMESTAMPTZ DEFAULT now(),UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,message TEXT NOT NULL,read BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS announcements(id SERIAL PRIMARY KEY,course_id INT REFERENCES courses(id) ON DELETE CASCADE,author_id INT REFERENCES users(id),title TEXT NOT NULL,body TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS messages(id SERIAL PRIMARY KEY,sender_id INT REFERENCES users(id),recipient_id INT REFERENCES users(id),course_id INT REFERENCES courses(id),body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS discussions(id SERIAL PRIMARY KEY,course_id INT REFERENCES courses(id) ON DELETE CASCADE,user_id INT REFERENCES users(id),parent_id INT REFERENCES discussions(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id SERIAL PRIMARY KEY,course_id INT REFERENCES courses(id) ON DELETE CASCADE,user_id INT REFERENCES users(id),rating INT CHECK(rating BETWEEN 1 AND 5),comment TEXT,UNIQUE(course_id,user_id));
CREATE TABLE IF NOT EXISTS activity_logs(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,detail TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_courses_pub ON courses(status,published);CREATE INDEX IF NOT EXISTS idx_enr_user ON enrollments(user_id);CREATE INDEX IF NOT EXISTS idx_prog_user ON progress(user_id);
CREATE INDEX IF NOT EXISTS idx_sub_assign ON submissions(assignment_id);CREATE INDEX IF NOT EXISTS idx_notif_user ON notifications(user_id,read);CREATE INDEX IF NOT EXISTS idx_att_course ON attendance(course_id,user_id);
